import { GenerativeAIJobType } from '../../GenerativeAIJobType';
import { IGenerativeAIJobResult } from '../../job/GenerativeAIJobResult';
import { ISearchResult } from '../../search';
import { PromptTypeText, PromptTypeVector } from './result';
/**
 * The AI prompt result Interface
 * Represents the result of an AI prompt.
 * @category AI
 */
export interface IGenerativeAIPromptResult extends IGenerativeAIJobResult {
    /**
     * The prompt AI job type.
     */
    type: GenerativeAIJobType.Prompt | GenerativeAIJobType.Inference | GenerativeAIJobType.Embed;
    /**
     * The output of the AI job.
     */
    output?: PromptTypeText | PromptTypeVector;
    /**
     * The relevant context used by the AI job.
     */
    context?: ISearchResult[];
    /**
     * The internal context used by the AI job.
     */
    internalContext?: {
        [key: string]: string;
    };
    /**
     * The file generated by the AI job.
     */
    resultFile?: string;
    /**
     * The tokens used by the AI job.
     */
    inputTokens?: number;
    /**
     * The tokens generated by the AI job.
     */
    outputTokens?: number;
    /**
     * The tokens used by the AI job, bucketed by type for billing. `base` holds
     * tokens billed at the model's list price; other buckets (cacheRead,
     * cacheWrite5m, cacheWrite1h, cached, audio, image, …) are converted to
     * base-token equivalents at billing time via the model's tokenRates.
     * Optional: connectors without per-type usage data keep reporting only the
     * flat inputTokens/outputTokens counts.
     */
    tokenBuckets?: {
        input?: Record<string, number>;
        output?: Record<string, number>;
    };
    /**
     * Per-request usage, one entry per provider API request (tool-loop
     * iterations and max_tokens continuations each count). Price tiers such as
     * `context-<N>k` are decided per request on that request's raw prompt
     * length, which the aggregate `tokenBuckets` cannot express once several
     * requests are summed. The aggregate fields above stay populated for
     * backward compatibility; consumers prefer `usageCalls` when present.
     */
    usageCalls?: IGenerativeAIUsageCall[];
}
/**
 * Token usage of a single provider API request, bucketed by type.
 * @category AI
 */
export interface IGenerativeAIUsageCall {
    input: Record<string, number>;
    output: Record<string, number>;
}
